tool_and_message_events.command:
/bin/bash -lc 'set -eu
tally_check_dir=$(mktemp -d "$PWD/.tally-check.XXXXXX")
mkdir "$tally_check_dir/release"
cp release/engineering-tally-fixture-1.0.2.tgz "$tally_check_dir/release/"
cd "$tally_check_dir"
npm install --global --prefix "$PWD/.tally" --cache "$PWD/.tally-cache" --offline --no-audit --no-fund --ignore-scripts ./release/engineering-tally-fixture-1.0.2.tgz
ls -l ./.tally/bin/tally
./.tally/bin/tally --help
./.tally/bin/tally --version
node --input-type=module <<'"'NODE'
import { spawnSync } from 'node:child_process';
import assert from 'node:assert/strict';

const run = args => {
  const result = spawnSync('./.tally/bin/tally', args, { encoding: 'utf8' });
  const { status, stdout, stderr } = result;
  console.log(JSON.stringify({ args, status, stdout, stderr }));
  return result;
};
const success = run(['sum', '2', '3', '--json']);
assert.equal(success.status, 0);
assert.equal(success.stdout, 'Calculating\\n{\"total\":5}\\n');
assert.equal(success.stderr, '');
assert.throws(() => JSON.parse(success.stdout), SyntaxError);
console.log('Whole stdout: JSON.parse rejected input');
const invalid = run(['sum', '2', 'abc', '--json']);
assert.equal(invalid.status, 2);
assert.equal(invalid.stdout, '');
assert.equal(invalid.stderr, 'Invalid number\\n');
NODE"

